.mobile-nav {
  transition: border-radius 0.5s cubic-bezier(0.77, 0.2, 0.05, 1);
}

.mobile-fullpage {
  transition: transform 0.5s cubic-bezier(0.77, 0.2, 0.05, 1);
}


span {
  width: 100%;
  height: 2px;
  background: #201f1d;
  border-radius: 2px;
  transition: transform 0.5s cubic-bezier(0.77, 0.2, 0.05, 1);
}

span:nth-child(odd) {
  margin-top: 1rem;
  transform-origin: center left;
}

span:nth-child(even) {
  margin-top: 0.6rem;
  transform-origin: center left;
}

.open-first {
  transform: translate(0.4rem, -0.6rem) rotate(42deg);
}

.open-second {
  transform: translate(0.4rem, 0.6rem) rotate(-42deg);
}
